const SB = 'https://wdjlellvhvsarivdpgou.supabase.co';
const entrada = $('Webhook').first().json;
const ANON = String((entrada.headers || {}).apikey || '');
const jwt = String((entrada.headers || {})['author' + 'ization'] || '').split(' ').pop();
const avaliacaoId = (entrada.body || {}).avaliacao_id;
if (!jwt || !/^[0-9a-f-]{36}$/i.test(String(avaliacaoId || ''))) throw new Error('Pedido inválido.');
const H = Object.fromEntries([['api' + 'key', ANON], ['Author' + 'ization', 'Bea' + 'rer ' + jwt]]);
const req = (o) => this.helpers.httpRequest({ json: true, ...o, headers: { ...H, ...(o.headers || {}) } });
const patch = (campos) => req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, body: { ...campos, etapa_atualizada_em: new Date().toISOString() }, headers: { Prefer: 'return=minimal' } });
const progresso = async (texto, zerar) => { try { const [r] = await req({ method: 'GET', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId + '&select=progresso' }); const atual = zerar ? (r.progresso || []).filter(p => p.tipo !== 'fotos') : (r.progresso || []); await req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, body: { progresso: [...atual, { em: new Date().toISOString(), texto, tipo: 'fotos' }] }, headers: { Prefer: 'return=minimal' } }); } catch (e) { } };

try {
  const [av] = await req({ method: 'GET', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId + '&select=id,endereco,bairro,cidade,uf,cep' });
  if (!av) throw new Error('Avaliação não encontrada ou sem acesso.');
  const amostras = await req({ method: 'GET', url: SB + '/rest/v1/avaliacoes_amostras?avaliacao_id=eq.' + avaliacaoId + '&selecionada=eq.true&select=id,endereco,condominio' });
  const numeroDe = (end) => { const partes = String(end || '').split(','); if (partes.length < 2) return null; const m = partes[1].match(/\d+/); return m ? m[0] : null; };
  const alvos = [];
  const numAv = numeroDe(av.endereco);
  if (numAv) alvos.push({ tipo: 'imovel', id: av.id, numero: numAv, caminho: avaliacaoId + '/streetview-imovel.jpg', endereco: [String(av.endereco).split(',').slice(0, 2).join(','), av.bairro, av.cidade, av.uf, av.cep, 'Brasil'].filter(Boolean).join(', ') });
  for (const a of amostras) {
    const n = numeroDe(a.endereco);
    if (!n) continue;
    alvos.push({ tipo: 'amostra', id: a.id, numero: n, caminho: avaliacaoId + '/streetview-amostra-' + a.id + '.jpg', endereco: [String(a.endereco).split(',').slice(0, 2).join(','), av.cidade, av.uf, 'Brasil'].filter(Boolean).join(', ') });
  }
  await progresso('Procurando no Google Street View a foto da fachada do imóvel' + (alvos.length > 1 ? ' e de ' + (alvos.length - 1) + ' comparável(is) com número' : '') + '…', true);
  if (!alvos.length) { await progresso('O endereço do imóvel está sem número, então não dá para tirar a foto da fachada.'); await patch({ etapa: 'selecionar_fotos', etapa_erro: null }); return []; }
  return alvos.map(a => ({ json: a }));
} catch (e) {
  await patch({ etapa: 'selecionar_fotos', etapa_erro: null }).catch(() => {});
  throw e;
}

const SB = 'https://wdjlellvhvsarivdpgou.supabase.co';
const entrada = $('Webhook').first().json;
const ANON = String((entrada.headers || {}).apikey || '');
const jwt = String((entrada.headers || {})['author' + 'ization'] || '').split(' ').pop();
const avaliacaoId = (entrada.body || {}).avaliacao_id;
const H = Object.fromEntries([['api' + 'key', ANON], ['Author' + 'ization', 'Bea' + 'rer ' + jwt]]);
const req = (o) => this.helpers.httpRequest({ json: true, ...o, headers: { ...H, ...(o.headers || {}) } });
const patch = (campos) => req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, body: { ...campos, etapa_atualizada_em: new Date().toISOString() }, headers: { Prefer: 'return=minimal' } });
const progresso = async (texto) => { try { const [r] = await req({ method: 'GET', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId + '&select=progresso' }); await req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, body: { progresso: [...(r.progresso || []), { em: new Date().toISOString(), texto, tipo: 'fotos' }] }, headers: { Prefer: 'return=minimal' } }); } catch (e) { } };
const alvos = $('Preparar endereços').all().map(i => i.json);
const geos = $('Google Geocoding').all().map(i => i.json);
const metas = $input.all().map(i => i.json);
const rad = (x) => x * Math.PI / 180;
const rumo = (a, b) => { const y = Math.sin(rad(b.lng - a.lng)) * Math.cos(rad(b.lat)); const x = Math.cos(rad(a.lat)) * Math.sin(rad(b.lat)) - Math.sin(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.cos(rad(b.lng - a.lng)); return Math.round((Math.atan2(y, x) * 180 / Math.PI + 360) % 360); };
const saida = [];
let imovelOk = false;
alvos.forEach((alvo, i) => {
  const g = geos[i] || {}, m = metas[i] || {};
  const r = (g.results || [])[0];
  if (g.status !== 'OK' || !r || m.status !== 'OK' || !m.location) return;
  const num = ((r.address_components || []).find(c => (c.types || []).includes('street_number')) || {}).long_name;
  if (String(num || '') !== String(alvo.numero)) return;
  if (alvo.tipo === 'imovel') imovelOk = true;
  const alvoPt = r.geometry.location, pano = m.location;
  saida.push({ json: { ...alvo, lat: alvoPt.lat, lng: alvoPt.lng, pano_id: m.pano_id, heading: rumo(pano, alvoPt), data_imagem: m.date || null, endereco_google: r.formatted_address, precisao: r.geometry.location_type } });
});
const imv = saida.find(s => s.json.tipo === 'imovel');
await progresso(imovelOk ? 'Encontramos imagem do Street View na frente do imóvel' + (imv && imv.json.data_imagem ? ' (de ' + imv.json.data_imagem + ')' : '') + '. Baixando a foto…' : 'Não há imagem do Street View exatamente nesse número.');
if (!saida.length) { await patch({ etapa: 'selecionar_fotos', etapa_erro: null }).catch(() => {}); return []; }
return saida;

const SB = 'https://wdjlellvhvsarivdpgou.supabase.co';
const entrada = $('Webhook').first().json;
const ANON = String((entrada.headers || {}).apikey || '');
const jwt = String((entrada.headers || {})['author' + 'ization'] || '').split(' ').pop();
const avaliacaoId = (entrada.body || {}).avaliacao_id;
const H = Object.fromEntries([['api' + 'key', ANON], ['Author' + 'ization', 'Bea' + 'rer ' + jwt]]);
const req = (o) => this.helpers.httpRequest({ json: true, ...o, headers: { ...H, ...(o.headers || {}) } });
const patch = (campos) => req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, body: { ...campos, etapa_atualizada_em: new Date().toISOString() }, headers: { Prefer: 'return=minimal' } });
const progresso = async (texto) => { try { const [r] = await req({ method: 'GET', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId + '&select=progresso' }); await req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_imoveis?id=eq.' + avaliacaoId, body: { progresso: [...(r.progresso || []), { em: new Date().toISOString(), texto, tipo: 'fotos' }] }, headers: { Prefer: 'return=minimal' } }); } catch (e) { } };
try {
  const esc = $('Escolher câmera').all().map(i => i.json);
  const ups = $input.all();
  let salvas = 0;
  for (let i = 0; i < esc.length; i++) {
    const e = esc[i], u = ups[i];
    if (!u || u.json.error) continue;
    salvas++;
    if (e.tipo === 'imovel') {
      await patch({ foto_imovel: { path: e.caminho, data_imagem: e.data_imagem, lat: e.lat, lng: e.lng, heading: e.heading, endereco_google: e.endereco_google } });
    } else {
      const [a] = await req({ method: 'GET', url: SB + '/rest/v1/avaliacoes_amostras?id=eq.' + e.id + '&select=fotos,fotos_origem' });
      if (!a) continue;
      const fotos = (a.fotos || []).filter(f => f !== e.caminho), origem = [];
      (a.fotos || []).forEach((f, k) => { if (f !== e.caminho) origem.push((a.fotos_origem || [])[k] || ''); });
      await req({ method: 'PATCH', url: SB + '/rest/v1/avaliacoes_amostras?id=eq.' + e.id, body: { fotos: [e.caminho, ...fotos], fotos_origem: ['google-streetview:' + (e.data_imagem || ''), ...origem] }, headers: { Prefer: 'return=minimal' } });
    }
  }
  await progresso('Pronto! ' + salvas + ' foto(s) do Street View salva(s).');
  await patch({ etapa: 'selecionar_fotos', etapa_erro: null });
  return [{ json: { ok: true, fotos_salvas: salvas } }];
} catch (e) {
  await patch({ etapa: 'selecionar_fotos', etapa_erro: null }).catch(() => {});
  throw e;
}
